let state={schemaVersion:1,title:'Тайны леса',description:'Разгадай кроссворд и узнай, что скрывает волшебный лес.',instructions:'Нажимай на вопрос или клетку и вводи ответ. Enter — проверить, пробел — сменить направление. Если будет сложно, попроси Листика о подсказке.',language:'ru',mode:'auto',words:defaultWords,size:22,accent:'#426347',background:'#fbf3e3',radius:4,gridFont:'Georgia',cat:true,catBubble:true,catScale:1,catMirror:false,messages:{},lives:5,lifeIcon:'♥',timerMode:'countdown',seconds:300,points:100,errorPenalty:10,hintPenalty:20,hintLimit:3,hintType:'letter',keyboard:false,showClues:false,autoCheck:false,foldYo:true,reduceMotion:false,contrast:false,sound:false,victoryTitle:'Лесные тайны раскрыты!',defeatTitle:'Попробуем ещё раз?',timeoutTitle:'Время приключения истекло',finalReview:false};
state.backgroundTransparency=0;state.backgroundDarkness=0;state.transparentBackground=false;state.questionColor='#263e35';state.questionBackground='#ffffff';state.questionTransparent=false;state.keyboardColor='#ffffff';state.keyboardTextColor='#263e35';state.keyboardBackground='#e9edf2';state.typography={};state.catStates={};state.buttonColor=state.accent;state.buttonTextColor='#fffdf4';state.letterColor='#35553a';state.buttonStyles={};
const designDefaults={cellColor:'#fffdf4',cellActiveColor:'#e4e9d1',cellSolvedColor:'#d7e3c3',cellWrongColor:'#f2d9c5',statsBackground:'#fffdf4',statsTextColor:'#263e35',statsLifeColor:'#b34c35',finalBackground:'#fffdf4',finalTextColor:'#263e35'};Object.assign(state,designDefaults);
