let finalPreview='victory';let buttonTarget='all';let catState='idle';let fontRole='grid';let section=location.hash==='#fonts'?'fonts':'crossword',history=[],future=[],variants=[],player=null,saveTimer=null,dirty=false,testMode=false,seed=7,db=null;
let best=[];for(let i=1;i<=40;i++){let v=E.generate(defaultWords,22,i);if(v.words.length>best.length){best=v.words;state.layout=v;}if(!v.missing.length)break;}
