function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function snapshot(){history.push(JSON.stringify(state));if(history.length>100)history.shift();future=[];}
function changed(rebuildPanel=false){dirty=true;$('#saveStatus').textContent='Сохраняем черновик…';$('#fileTitle').textContent=state.title;renderGame();if(rebuildPanel)renderPanel();updateHistory();clearTimeout(saveTimer);saveTimer=setTimeout(persist,450);}
function updateHistory(){$('#undoBtn').disabled=!history.length;$('#redoBtn').disabled=!future.length;}
function commit(fn,rebuild=false){snapshot();fn();changed(rebuild);}
function renderGame(){
 player?.destroy();player=null;const host=$('#gameContainer');
 if(!state.layout.words.length){host.classList.remove('cw-stage');host.innerHTML='<div class="empty-project"><strong>Здесь появится ваш кроссворд</strong><p>Добавьте слово или загрузите свой список в разделе «Кроссворд».</p></div>';$('#layoutStats').textContent='0 размещённых слов';return;}
 const previewFinal=section==='final'&&!testMode;
 player=CrosswordGame.mount(host,state,{editor:!testMode,startScreen:!previewFinal&&state.showStartScreen!==false&&(testMode||!state.hideStartScreenInEditor),selectedOverlay,onOverlaySelect:kind=>selectedOverlay=kind,onOverlayChange:(kind,rect)=>commit(()=>state[kind+'Rect']=rect),onDropWord:!testMode&&state.mode==='manual'?placeDroppedWord:null});
 if(previewFinal)player.previewFinal(finalPreview);
 $('#layoutStats').textContent=state.layout.words.length+' слов · '+state.layout.cols+' × '+state.layout.rows+' клеток · '+state.layout.crossings+' пересечений';
}
function field(label,key,type='text',extra=''){return '<label class="field"><span>'+label+'</span><input data-key="'+key+'" type="'+type+'" value="'+esc(state[key]??designDefaults[key])+'" '+extra+'></label>';}
function backgroundSlider(label,key){const value=Math.max(0,Math.min(100,Number(state[key])||0));return '<label class="field"><span>'+label+' <output data-background-value="'+key+'">'+value+'%</output></span><input data-key="'+key+'" type="range" min="0" max="100" step="1" value="'+value+'"></label>';}
function area(label,key){return '<label class="field"><span>'+label+'</span><textarea data-key="'+key+'">'+esc(state[key])+'</textarea></label>';}
function select(label,key,options){return '<label class="field"><span>'+label+'</span><select data-key="'+key+'">'+options.map(([v,l])=>'<option value="'+v+'" '+(String(state[key])===String(v)?'selected':'')+'>'+l+'</option>').join('')+'</select></label>';}
function toggle(label,key){return '<label class="toggle-row">'+label+'<input data-key="'+key+'" type="checkbox" '+(state[key]?'checked':'')+'></label>';}
function wordList(){return '<div class="words-head"><strong style="font-size:11px">Слова и вопросы</strong><span class="pill">'+state.words.length+' слов</span></div>'+state.words.map((w,i)=>'<div class="word-row" data-edit="'+esc(w.id)+'" role="button" tabindex="0" draggable="'+(state.mode==='manual')+'"><span class="word-n">'+(i+1)+'</span><div class="word-text"><strong>'+esc(w.answer)+'</strong><small>'+esc(w.clue)+'</small></div><span class="word-arrow">'+(state.layout.words.find(p=>p.id===w.id)?.dir==='v'?'↓':'→')+'</span></div>').join('')+'<button class="add-word" id="addWord">＋ Добавить слово</button>'+(state.words.length?'<button class="quiet generate" id="clearAllWords">\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0432\u0441\u0435 \u0441\u043b\u043e\u0432\u0430</button>':'');}
function renderNav(){$('#navigation').innerHTML=sections.map((s,i)=>(i===6?'<div class="nav-group"></div>':'')+'<button class="nav-item '+(section===s[0]?'active':'')+'" data-section="'+s[0]+'"><span class="nav-icon">'+s[1]+'</span><span class="nav-text">'+s[2]+'</span></button>').join('');$('#navigation').querySelectorAll('button').forEach(b=>b.onclick=()=>{const before=section;section=b.dataset.section;renderNav();renderPanel();if(section==='final'||before==='final')renderGame();$('.settings').scrollTop=0;});}
