if(section==='cat')html='<div class="subheading"><strong>Галерея персонажей</strong><span class="pill">'+CrosswordCompanions.items.length+'</span></div><div class="companion-gallery">'+CrosswordCompanions.items.map(item=>'<button class="companion-choice '+(state.companionId===item.id?'selected':'')+'" data-companion="'+item.id+'" aria-pressed="'+String(state.companionId===item.id)+'"><img src="'+item.thumbnail+'" alt="" loading="lazy"><span>'+item.name+'</span></button>').join('')+'</div>'+((state.companionId==='custom'||state.catStates?.idle)?'<div class="helper-card"><img src="'+esc(CrosswordCompanions.source(state))+'" alt=""><strong>Своя GIF</strong></div>':'')+'<button class="outline generate" id="catUpload">↥ Загрузить свою GIF или картинку</button><button class="quiet generate" id="downloadCat">↓ Скачать выбранную GIF</button>'+toggle('Показывать персонажа','cat')+toggle('Включить реплики','catBubble')+toggle('Зеркальное отражение','catMirror')+'<div class="hint-box">Нажмите на персонажа или реплику в предпросмотре. Перетащите зелёную рамку для перемещения, потяните за угол для изменения размера.</div><button class="outline generate" id="resetPlacement">Сбросить расположение</button><div class="section-rule"></div><strong>Оформление реплики</strong>'+field('Фон реплики','bubbleBackground','color')+toggle('Прозрачный фон реплики','bubbleTransparent')+field('Цвет текста реплики','bubbleColor','color')+field('Размер текста, px','bubbleFontSize','number','min="10" max="72"')+'<div class="section-rule"></div><strong>Реплики и состояния</strong>'+catStatesHTML()+[['idle','Знакомство'],['correct','Правильный ответ'],['wrong','Ошибка'],['hint','Подсказка'],['lowtime','Мало времени'],['onelife','Одна жизнь'],['victory','Победа'],['defeat','Поражение'],['timeout','Время вышло']].map(([k,l])=>'<label class="field"><span>'+l+'</span><textarea data-message="'+k+'" placeholder="Стандартная реплика">'+esc(state.messages[k]||'')+'</textarea></label>').join('');
if(section==='hints')html=field('Количество подсказок','hintLimit','number','min="0" max="50"')+select('Действие подсказки','hintType',[['letter','Открыть случайную букву'],['first','Открыть первую неверную букву'],['author','Показать текст автора']])+field('Штраф за подсказку, баллов','hintPenalty','number','min="0" max="1000"')+'<div class="hint-box">Дополнительный текст подсказки задаётся отдельно для каждого слова в разделе «Вопросы».</div>';
if(section==='rules')html=select('Количество жизней','lives',[[0,'Без ограничений'],...Array.from({length:10},(_,i)=>[i+1,(i+1)+' жизней'])])+select('Значок жизни','lifeIcon',[['♥','♥ Сердечко'],['✦','✦ Звезда'],['♧','♧ Листочек']])+select('Таймер','timerMode',[['none','Без таймера'],['countdown','Обратный отсчёт'],['stopwatch','Секундомер']])+(state.timerMode==='countdown'?field('Длительность в секундах','seconds','number','min="10" max="7200"'):'')+'<div class="section-rule"></div>'+field('Баллы за слово','points','number','min="1" max="1000"')+field('Штраф за ошибку','errorPenalty','number','min="0" max="1000"');
