function warnings(){let errors=E.validate(state.words,state.layout,+state.size);return errors.length?'<div class="error" style="margin-top:12px">'+errors.map(esc).join('<br>')+'</div>':'';}
function variantsHTML(){if(!variants.length)return '';return '<div class="section-rule"></div><div class="subheading"><strong>Варианты раскладки</strong><span class="pill">'+variants.length+'</span></div>'+variants.map((v,i)=>{let b=E.board(v.words);return '<div class="variant"><div class="mini-grid" style="grid-template-columns:repeat('+v.cols+',1fr)">'+Array.from({length:v.rows*v.cols},(_,j)=>'<i class="'+(b.has(Math.floor(j/v.cols)+','+j%v.cols)?'filled':'')+'"></i>').join('')+'</div><div><strong>Вариант '+(i+1)+'</strong><small>'+v.words.length+'/'+state.words.length+' слов · '+v.cols+'×'+v.rows+'<br>'+v.crossings+' пересечений</small></div><button data-variant="'+i+'">Выбрать</button></div>';}).join('');}
function manualHTML(){return '<div class="section-rule"></div><div class="hint-box">Координаты отсчитываются от 1. Измените позицию и нажмите «Разместить». Пересечения и соседство проверяются автоматически.</div><div class="manual-list">'+state.words.map(w=>{let p=state.layout.words.find(x=>x.id===w.id)||{r:0,c:0,dir:'h'};return '<div class="word-row" data-place-id="'+w.id+'"><strong>'+esc(w.answer)+'</strong><div class="row"><input aria-label="Строка" type="number" data-r value="'+(p.r+1)+'" min="1" max="40"><input aria-label="Столбец" type="number" data-c value="'+(p.c+1)+'" min="1" max="40"><select aria-label="Направление" data-dir><option value="h">→</option><option value="v" '+(p.dir==='v'?'selected':'')+'>↓</option></select><button class="inline-button" data-place>Разместить</button></div></div>';}).join('')+'</div>';}
