 document.querySelectorAll('[data-final-preview]').forEach(button=>button.onclick=()=>{finalPreview=button.dataset.finalPreview;renderPanel();renderGame();});
 document.querySelectorAll('[data-final-upload]').forEach(button=>button.onclick=()=>uploadMedia(button.dataset.finalUpload));
 document.querySelectorAll('[data-final-clear]').forEach(button=>button.onclick=()=>commit(()=>delete state[button.dataset.finalClear],true));
