$('#helpBtn').onclick=()=>modal('<h2>Ваша лесная мастерская</h2><p>1. Добавьте слова и вопросы по одному или списком.<br>2. Нажмите «Сгенерировать варианты» и выберите раскладку.<br>3. Настройте цвета, помощника, жизни и подсказки.<br>4. Перейдите в «Тестировать» и пройдите игру.<br>5. Сохраните проект или скачайте автономный HTML.</p><div class="hint-box">Нажатие на слово в списке открывает редактор ответа, вопроса и подсказки. В ручном режиме можно изменить координаты и направление слов.</div>');
async function initDB(){try{db=await new Promise((resolve,reject)=>{let req=indexedDB.open('forest-crossword',1);req.onupgradeneeded=()=>req.result.createObjectStore('drafts');req.onsuccess=()=>resolve(req.result);req.onerror=reject;});let saved=await new Promise((resolve,reject)=>{let req=db.transaction('drafts').objectStore('drafts').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=reject;});if(saved){try{validateProject(saved);await upgradeProject(saved);state={...state,...saved};renderPanel();renderGame();$('#fileTitle').textContent=state.title;}catch{toast('Предыдущий черновик не удалось восстановить. Открыт пример.');}}}catch{toast('Автосохранение недоступно. Сохраняйте проект в файл.');}}
async function persist(){if(!db){$('#saveStatus').textContent='Сохраните проект в файл';return;}try{await new Promise((resolve,reject)=>{let tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').put(structuredClone(state),'current');tx.oncomplete=resolve;tx.onerror=reject;});$('#saveStatus').textContent='Черновик сохранён в браузере';dirty=false;}catch{$('#saveStatus').textContent='Сохраните проект в файл';}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});renderNav();renderPanel();renderGame();updateHistory();initDB();

