async function uploadFont(){const input=document.createElement('input');input.type='file';input.accept='.woff,.woff2';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>2*1024*1024){toast('Размер шрифта должен быть не более 2 МБ.');return;}try{const data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});const font=new FontFace('Мой шрифт','url('+data+')');await font.load();document.fonts.add(font);commit(()=>{state.customFont=data;state.gridFont='Мой шрифт';},true);toast('Шрифт загружен и будет встроен в HTML.');}catch{toast('Не удалось открыть шрифт.');}};input.click();}
function placeDroppedWord(id,r,c){const w=state.words.find(w=>w.id===id);if(!w)return;const old=state.layout.words.find(x=>x.id===id),nw={...w,r,c,dir:old?.dir||'h'},other=state.layout.words.filter(x=>x.id!==id);if(!E.fits(nw,other,+state.size)){toast('Здесь нельзя разместить слово: проверьте пересечения.');return;}commit(()=>{const words=E.number([...other,nw]);const cells=words.flatMap(E.cells);state.layout={...state.layout,words,rows:Math.max(...cells.map(q=>q.r))+1,cols:Math.max(...cells.map(q=>q.c))+1,crossings:[...E.board(words).values()].filter(q=>q.words.length>1).length,missing:state.words.filter(w=>!words.some(x=>x.id===w.id)).map(w=>w.id)};},true);}

function catStatesHTML(){const names={idle:'Ожидание',correct:'Правильный ответ',wrong:'Ошибка',hint:'Подсказка',lowtime:'Мало времени',onelife:'Одна жизнь',victory:'Победа',defeat:'Поражение',timeout:'Время вышло'};return '<label class="field"><span>Своя анимация для состояния</span><select id="catState">'+Object.entries(names).map(([k,l])=>'<option value="'+k+'" '+(catState===k?'selected':'')+'>'+l+'</option>').join('')+'</select></label><button class="outline generate" id="catAnimationUpload">↥ Загрузить GIF / изображение</button>'+(state.catStates?.[catState]?'<button class="quiet generate" id="catAnimationClear">Вернуть выбранного персонажа</button>':'')+'<div class="little-info">GIF сохраняется с анимацией. Без своего файла используется выбранный персонаж.</div>';}

async function readQuestionMedia(file,image){if(file.size>8*1024*1024)throw Error('Максимальный размер медиа вопроса — 8 МБ.');if(image){toast('Сжимаем медиа вопроса…');const result=await CrosswordMedia.optimize(file,{maxEdge:960,onProgress:value=>toast('Сжатие GIF: '+Math.round(value*100)+'%')});toast(mediaSummary(result));return result.data;}return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}

function buttonStylesHTML(){const targets={all:'Все кнопки',check:'Проверить слово',hint:'Подсказка',keyboard:'Значок клавиатуры',keys:'Клавиши клавиатуры',next:'Следующий вопрос',play:'Начало игры',retry:'Повтор игры'};const style=state.buttonStyles?.[buttonTarget]||{};return '<label class="field"><span>Настроить отдельную кнопку</span><select id="buttonTarget">'+Object.entries(targets).map(([k,l])=>'<option value="'+k+'" '+(buttonTarget===k?'selected':'')+'>'+l+'</option>').join('')+'</select></label>'+(buttonTarget==='all'?'<div class="little-info">Общие цвета выше применяются ко всем игровым кнопкам.</div>':'<div class="row"><label class="field"><span>Фон</span><input data-button-prop="background" type="color" value="'+(style.background||state.buttonColor||state.accent)+'"></label><label class="field"><span>Текст</span><input data-button-prop="text" type="color" value="'+(style.text||state.buttonTextColor||'#fffdf4')+'"></label><label class="field"><span>Рамка</span><input data-button-prop="border" type="color" value="'+(style.border||state.buttonColor||state.accent)+'"></label></div>');}

async function upgradeProject(p){p.bubbleFontSize??=p.typography?.bubble?.size||18;p.bubbleColor??=p.typography?.bubble?.color||'#263e35';p.questionColor??=p.typography?.clue?.color||'#263e35';p.keyboardColor??=p.buttonStyles?.keys?.background||p.buttonColor||'#ffffff';p.keyboardTextColor??=p.buttonStyles?.keys?.text||p.buttonTextColor||'#263e35';if(p.catAsset&&typeof crypto?.subtle?.digest==='function'){try{const encoded=p.catAsset.split(',')[1];const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(['05acf6d35562272f1550af7d12d021ad9b6ed5dea6def92a3888d295ca4e1743','972d0f362b37245c6af324ee12fcc0144d7cce45d27822cfe0735117d05db149','50542d02262eaddefa81fcc17c1366dd1b9c1d1e15d459499462a0499aa2a9de','627b7834c755f068ceba4d11e053a2448121c82da766ae5887f2e5813ef6e9d9','455e8edcb178051a4e6d50aa9e2eae61d5dcb926f06736fa29aa3e1346910d9a'].includes(hash)){delete p.catAsset;delete p.catStaticAsset;p.reduceMotion=false;p.companionId='cat';}}catch{}}if(!p.companionId)p.companionId=p.catAsset?'custom':'cat';return p;}
